// Demo projects. All of them use real packages and real versions; the npm
// lockfile was generated by npm itself (`npm install --package-lock-only
// --ignore-scripts`), not written by hand. Files are loaded lazily.

const loaders = import.meta.glob('./samples/**/*', { query: '?raw', import: 'default' })

export const SAMPLES = [
  {
    id: 'express-shop',
    title: 'Tienda Express (npm)',
    format: 'package-lock.json',
  },
  {
    id: 'flask-api',
    title: 'API Flask de 2021 (pip)',
    format: 'requirements.txt',
  },
  {
    id: 'java-sbom',
    title: 'Servicio Java (SBOM)',
    format: 'CycloneDX',
  },
  {
    id: 'fastapi-clean',
    title: 'Servicio al día (pip)',
    format: 'requirements.txt',
  },
  {
    id: 'broken-lock',
    title: 'Lockfile con conflicto de merge',
    format: 'package-lock.json',
  },
]

/** -> Promise<[{path, content}]> */
export async function loadSample(id) {
  const prefix = `./samples/${id}/`
  const entries = Object.entries(loaders).filter(([path]) => path.startsWith(prefix))
  const files = await Promise.all(
    entries.map(async ([path, load]) => ({ path: path.slice(prefix.length), content: await load() })),
  )
  return files.sort((a, b) => (a.path < b.path ? -1 : 1))
}
